import{d as r,C as a,o as d,c as g,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十七章","description":"《正易心法》第三十七章——五行之数，须究落处：天一生水坎孕于乾金（立冬）、至地十为成数（成形）；批评盲随古人不知落处；并举先天卦与《太玄》的倍数规律、以时物（祖父子孙、正月至六月）明数之所以明理。","frontmatter":{"title":"正易心法·第三十七章","description":"《正易心法》第三十七章——五行之数，须究落处：天一生水坎孕于乾金（立冬）、至地十为成数（成形）；批评盲随古人不知落处；并举先天卦与《太玄》的倍数规律、以时物（祖父子孙、正月至六月）明数之所以明理。","category":"guide","aliases":["正易心法第三十七章","五行之数须究落处","成象与成形"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-37.md","filePath":"yijing/zheng-yi-xin-fa/chapter-37.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-37.md"},x=r({...c,setup(u){const i=[{id:"z37-01",label:"一、五行须究落处",showLabel:!0,sentences:[["五行之数，须究",{text:"落处",glossary:"luochu"},"。",{text:"应数",glossary:"yingshu"},"倍数，亦明",{text:"特时",glossary:"teshi"},"。"]],note:["五行之数，必须追究它真正落脚的地方；应数与倍数，也能说明特定时节的道理。（**本章是全书少有的跨系统综合章**：从五行生成数，一路推到先天卦序与《太玄》的倍数规律，最后落到「时物」——**数、卦、时节、生命，四者打通。**）"]},{id:"z37-02",label:"二、五行生数成象",showLabel:!0,sentences:[["天一生水，坎之气",{text:"孕于",glossary:"yunyu"},"乾金，立冬节也。地二生火，离之气孕于巽木，立夏节也。天三生木，震之气孕于艮水，山高地厚，水泉出焉，立春节也。地四生金，兑之气孕于坤土，立秋节也。天五盛土，离寄戊而土气孕于离火，长夏节也。凡此皆言其",{text:"成象",glossary:"chengxiang"},"矣。"]],note:["天一生水：坎之气孕育于乾金，对应立冬节；地二生火：离之气孕育于巽木，对应立夏节；天三生木：震之气孕育于艮水（山高地厚，水泉出于其间），对应立春节；地四生金：兑之气孕育于坤土，对应立秋节；天五盛土：离寄戊土，土气孕育于离火，对应长夏节。以上都是说五行「成象」的阶段。（**「孕于」二字要读准**：是「乾金孕育了坎之气」——**母（生者）孕育子（被生者），这正是五行相生的方向。** 原文「地生四金」当作「地四生金」，语序倒置。「成象」＝气已有象而未成形。）"]},{id:"z37-03",label:"三、五行成数成形",showLabel:!0,sentences:[["天一与地六合而成水，乾坎合而成水于金，冬至节也。地二与天七合而成火，巽离合而火成于木，夏至节也。天三与地八合而成木，艮震合木成于水，春分节也。地四与天九合而成金，坤兑合而金成于土，秋分节也。天五与地十合而成土，离寄于己而土成于火也。凡此，皆言其",{text:"成形",glossary:"chengxing"},"矣。"]],note:["天一与地六合而成水：乾坎相合、水成于金，对应冬至节；地二与天七合而成火：巽离相合、火成于木，对应夏至节；天三与地八合而成木：艮震相合、木成于水，对应春分节；地四与天九合而成金：坤兑相合、金成于土，对应秋分节；天五与地十合而成土：离寄己土、土成于火。以上都是说五行「成形」的阶段。（**与生数严格对举**：生数配「立」节（立冬、立夏、立春、立秋、长夏），成数配「分／至」节（冬至、夏至、春分、秋分）。**从「立」到「分／至」，正是一个五行从孕育到成形的完整周期**——即生数到成数的时间展开。原文「合二成火」之「二」当为「而」之讹。）"]},{id:"z37-04",label:"四、盲随古人",showLabel:!0,sentences:[["夫以五言相成数，虽儿童亦能诵。要其义实。纵老壮亦不知落处也。是之谓",{text:"盲随古人",glossary:"mangsuiGuren"},"，何以见《易》乎？"]],note:["用五行来说明相生相成之数，就算是儿童也能背诵；但要追究其义理真正落脚的地方，即便是老成之人也不知道。这就叫做盲目跟随古人，怎么能见到《易》的真义呢？（**这是全书语气最强的批评之一**——「虽儿童亦能诵」对「纵老壮亦不知落处」，**两个极端并置，落差极刺目。批评的实质很清楚：知识 ≠ 理解，背诵 ≠ 见《易》。**）"]},{id:"z37-05",label:"五、先天卦之倍数",showLabel:!0,sentences:[["以至先天诸卦，初以一阴一阳相间，次以二阴二阳相间，",{text:"倍数",glossary:"beishu"},"至三十二阴三十二阳相间。"]],note:["乃至先天诸卦：最初是一阴一阳相间，接着是二阴二阳相间，按倍数递增到三十二阴三十二阳相间。（**这是 2 的幂次**：1→2→4→8→16→32。**先天卦的世界是二元的**——阴与阳两个基本单位，一层一层翻倍展开。）"]},{id:"z37-06",label:"六、太玄诸首之倍数",showLabel:!0,sentences:[["《",{text:"太玄",glossary:"taixuan"},"》诸首，初以一阴一阳相间，此以三阳三阴相间，倍数至二十七阴二十七阳相间。此其理何在哉？"]],note:["《太玄》诸首：最初也是一阴一阳相间，接着是三阳三阴相间，按倍数递增到二十七阴二十七阳相间。这其中的道理在哪里？（**这是 3 的幂次**：1→3→9→27。**《太玄》的世界是三元的**——扬雄以「三才」（天、地、人）为基，**与《易》的二元并行而不相废。** 麻衣只问「其理何在」，**不作褒贬**——这本身就是一个态度。）"]},{id:"z37-07",label:"七、以时物推之",showLabel:!0,sentences:[["以时物推之，自祖父子孙，有众寡之渐。自正二三四五六月，有",{text:"微盛之滋",glossary:"weishengZhizi"},"，皆数之所以明理也。"]],note:["用时间与万物来推演：从祖父子孙，有多寡渐变的规律；从正月到六月，有阳气从微到盛的滋长——这都是用数来说明理的方式。（**两个最直观的节律**：**祖父子孙**（1→2→4→8）是**生命**的倍数增长，正是先天卦序倍数的生物学原型；**正月至六月**（一阳→六阳）是**时间**上的线性递增，正是阴阳消息的展开。**麻衣的意思很清楚：数不是悬空的，它落在生命的繁衍与阳气的消长上**——这就是本章标题所说的「以时物明理」。）"]},{id:"z37-08",label:"八、应数见前说",showLabel:!0,sentences:[["应数见前说。"]],note:["应数之说，见前文。（**这是麻衣的自注语**——「应数」指天地之数两两相配（一六、二七、三八、四九、五十），其说已见于前文，此处不再重复。**一个短句收尾，正是麻衣一贯的风格：说清了就停。**）"]}],l=[{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"真正落脚的地方。全书核心词，本章第一次用于五行之数。"},{id:"yingshu",term:"应数",pinyin:"yìng shù",meaning:"天地之数两两相应（一六、二七、三八、四九、五十）。"},{id:"teshi",term:"特时",pinyin:"tè shí",meaning:"特定的时节。五行生成与节气的对应。"},{id:"yunyu",term:"孕于",pinyin:"yùn yú",meaning:"孕育于。气在某卦中孕育，尚未成形——「乾金孕育坎之气」，即五行相生的方向。"},{id:"chengxiang",term:"成象",pinyin:"chéng xiàng",meaning:"气已有象，但尚未成形（生数阶段）。对应「立冬、立夏、立春、立秋、长夏」诸节。"},{id:"chengxing",term:"成形",pinyin:"chéng xíng",meaning:"气已成形，落实为物（成数阶段）。对应「冬至、夏至、春分、秋分」诸节。"},{id:"mangsuiGuren",term:"盲随古人",pinyin:"máng suí gǔ rén",meaning:"盲目跟随古人。麻衣批评只知诵数、不知义理落处的学者。"},{id:"beishu",term:"倍数",pinyin:"bèi shù",meaning:"加倍递增的数。先天卦为 2 的幂次，太玄为 3 的幂次。"},{id:"taixuan",term:"太玄",pinyin:"tài xuán",meaning:"扬雄《太玄经》，仿《易》而作，以三为基数（三才），共八十一首。"},{id:"weishengZhizi",term:"微盛之滋",pinyin:"wēi shèng zhī zī",meaning:"从微弱到旺盛的滋长。正月至六月，阳气从微到盛。"}];return(b,n)=>{const p=a("DaoTextReading"),o=a("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十七章" tabindex="-1">正易心法·第三十七章 <a class="header-anchor" href="#正易心法·第三十七章" aria-label="Permalink to &quot;正易心法·第三十七章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是全书少有的<strong>跨系统综合章</strong>，三层内容：</p><p><strong>第一层：五行生数与成数</strong></p><table tabindex="0"><thead><tr><th>五行</th><th>生数（成象）</th><th>孕于</th><th>生节</th><th>成数（成形）</th><th>成于</th><th>成节</th></tr></thead><tbody><tr><td>水</td><td>天一</td><td>乾金</td><td>立冬</td><td>地六</td><td>金</td><td>冬至</td></tr><tr><td>火</td><td>地二</td><td>巽木</td><td>立夏</td><td>天七</td><td>木</td><td>夏至</td></tr><tr><td>木</td><td>天三</td><td>艮水</td><td>立春</td><td>地八</td><td>水</td><td>春分</td></tr><tr><td>金</td><td>地四</td><td>坤土</td><td>立秋</td><td>天九</td><td>土</td><td>秋分</td></tr><tr><td>土</td><td>天五</td><td>离火</td><td>长夏</td><td>地十</td><td>火</td><td>—</td></tr></tbody></table><p><strong>第二层：批评「盲随古人」</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「虽儿童亦能诵」对「纵老壮亦不知落处」</span></span>
<span class="line"><span>知识 ≠ 理解，背诵 ≠ 见《易》</span></span></code></pre></div><p><strong>第三层：倍数规律与时物验证</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天卦：2 的幂次（1→2→4→8→16→32）</span></span>
<span class="line"><span>《太玄》：3 的幂次（1→3→9→27）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以时物推之：</span></span>
<span class="line"><span>  祖父子孙，有众寡之渐（1→2→4→8）</span></span>
<span class="line"><span>  正月至六月，有微盛之滋（一阳→六阳）</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「孕于」与「成于」的分工</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「孕于」（生数）＝ 子在母腹，有象无形</span></span>
<span class="line"><span>「成于」（成数）＝ 子已出生，有形可见</span></span>
<span class="line"><span></span></span>
<span class="line"><span>水孕于金：金生水（五行相生）</span></span>
<span class="line"><span>火孕于木：木生火</span></span>
<span class="line"><span>木孕于水：水生木</span></span>
<span class="line"><span>金孕于土：土生金</span></span>
<span class="line"><span>土孕于火：火生土</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 五行相生的方向，正是「孕育」的方向</span></span>
<span class="line"><span>  这不是抽象的数字游戏，是气在节气中真实流动的轨迹</span></span></code></pre></div><p><strong>生数与成数的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生数 + 5 = 成数</span></span>
<span class="line"><span>  1 + 5 = 6（水）    2 + 5 = 7（火）</span></span>
<span class="line"><span>  3 + 5 = 8（木）    4 + 5 = 9（金）    5 + 5 = 10（土）</span></span></code></pre></div><p><strong>节气的时间分布</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「立X节」  = 成象（气开始孕育）</span></span>
<span class="line"><span>「X分／X至」= 成形（气完全成形）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>从「立」到「分／至」，正好是一个五行从孕育到成形的周期</span></span>
<span class="line"><span>= 生数到成数的时间展开</span></span></code></pre></div><p><strong>先天卦与《太玄》的世界观差异</strong>：</p><table tabindex="0"><thead><tr><th></th><th>基础</th><th>倍数</th><th>世界观</th></tr></thead><tbody><tr><td>《易》</td><td>两仪（阴／阳）</td><td>2 的幂次</td><td>二元：一切都可以二分</td></tr><tr><td>《太玄》</td><td>三才（天／地／人）</td><td>3 的幂次</td><td>三元：一切在三才框架内展开</td></tr></tbody></table><p><strong>麻衣并不评判哪个更好，只说「此其理何在哉」</strong>——两个系统各有其内在逻辑，都能用「时物」来验证。</p><p><strong>「时物」验证的两例</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>祖父子孙的「众寡之渐」：祖（1）→ 父（2）→ 子（4）→ 孙（8）</span></span>
<span class="line"><span>= 2 的幂次增长 = 先天卦序倍数的生物学原型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正月到六月的「微盛之滋」：一阳→二阳→三阳→四阳→五阳→六阳</span></span>
<span class="line"><span>= 阳气逐月递增 = 倍数在时间轴上的线性展开</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把生数／成数两表并列看：<strong>「孕于」与「成于」的分别</strong>；</li><li>再读「盲随古人」——<strong>这是本章的分量所在</strong>；</li><li>最后看倍数规律：<strong>2 的幂次与 3 的幂次，两种世界观。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>须究落处</strong>：五行之数要有落脚点。</li><li><strong>生数（成象）</strong>：天一至天五，孕于某行，对应「立」节。</li><li><strong>成数（成形）</strong>：地与天合，成于某行，对应「分／至」节。</li><li><strong>盲随古人</strong>：儿童能诵，老壮不知落处。</li><li><strong>先天倍数</strong>：2 的幂次至三十二。</li><li><strong>太玄倍数</strong>：3 的幂次至二十七。</li><li><strong>时物为证</strong>：祖父子孙、正月至六月。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,26)),e(p,{colophon:"五行之数 · 须究落处 · 成象成形 · 何异《太玄》",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十七章原文",sections:i,glossary:l}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文「地生四金」语序倒置，当作「地四生金」；「地二与天七合二成火」之「二」当为「而」之讹；「天五盛土」一作「天五生土」。以上说明而不径改。本章所引《太玄》，为扬雄仿《易》之作，以三为基数。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"须究落处",pinyin:["luò","chù"],meaning:"五行之数必须追究真正落脚的地方——本章的批评正落在「虽儿童亦能诵，纵老壮亦不知落处」。"},{term:"孕于 · 成于",pinyin:["yùn","yú"],meaning:"孕于（生数）＝子在母腹，有象无形；成于（成数）＝子已出生，有形可见。方向即五行相生。"},{term:"成象与成形",pinyin:["chéng","xiàng"],meaning:"成象＝立冬立夏立春立秋长夏诸节（生数）；成形＝冬至夏至春分秋分诸节（成数）。"},{term:"先天倍数",pinyin:["bèi","shù"],meaning:"先天卦以一阴一阳相间起，按 2 的幂次增至三十二阴三十二阳——二元世界的结构。"},{term:"太玄倍数",pinyin:["tài","xuán"],meaning:"《太玄》以一阴一阳起，按 3 的幂次增至二十七——三元（三才）世界的结构。麻衣只问其理，不判优劣。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>跨系统综合章</strong>：从五行生成数（成象／成形），到对「盲随古人」的批评，再到先天卦与《太玄》的倍数规律，最后以「时物」（祖父子孙、正月至六月）为证。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「孕于」与「成于」的分工</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生数（成象）：气已有象而未成形 —— 对应「立」节</span></span>
<span class="line"><span>成数（成形）：气已成形落实为物 —— 对应「分／至」节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「水孕于金」＝金生水（五行相生）</span></span>
<span class="line"><span>= 相生的方向，正是「孕育」的方向</span></span>
<span class="line"><span>= 不是抽象的数字游戏，是气在节气中真实流动的轨迹</span></span></code></pre></div><p><strong>「其理则一」的两个系统</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天卦：2 的幂次（1→2→4→8→16→32）＝ 二元世界</span></span>
<span class="line"><span>《太玄》：3 的幂次（1→3→9→27）    ＝ 三元世界</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣只问「此其理何在哉」，不作褒贬</span></span></code></pre></div><p><strong>「时物」验证的两例</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>祖父子孙：1→2→4→8（众寡之渐，2 的幂次）</span></span>
<span class="line"><span>正月至六月：一阳→六阳（微盛之滋，线性递增）</span></span>
<span class="line"><span>皆数之所以明理也</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把生数／成数两表并列看：<strong>「孕于」与「成于」的分别是本章的钥匙</strong>；</li><li>读「盲随古人」时慢一点：<strong>「虽儿童亦能诵」对「纵老壮亦不知落处」</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「落处是节气与时物」——那节气与时物是《易》发现的，还是《易》定义的？</strong> 我的看法：<strong>麻衣会把这个问题当作「容心」来拒斥</strong>——在他看来，<strong>冬至那天水气「成形」是自然如此，不是命名的结果</strong>。但<strong>从今天的眼光看，「冬至」本身就是一个观测与命名的产物</strong>。<strong>这里有一个不可消除的张力：一旦你承认「节气是人的划界」，那么「落在节气上」就带上了一层人为性。</strong> 我不认为麻衣没想到这一点，<strong>但他选择了另一条路</strong>：<strong>他的「落处」不在「谁先谁后」，而在「是否可验证」</strong>——<strong>冬至阳极阴生、仲冬水泉动，这些是可观察的</strong>。<strong>在可观察这一点上，「落处」是实在的；在「谁定义谁」这一点上，它可能是循环的。</strong> 而全书的力量，恰恰在可观察的那一面。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>五行之数，必须追究它真正落脚的地方；应数与倍数，也能说明特定时节的道理。</p><p>天一生水：坎之气孕育于乾金，对应立冬节；地二生火：离之气孕育于巽木，对应立夏节；天三生木：震之气孕育于艮水（山高地厚，水泉出于其间），对应立春节；地四生金：兑之气孕育于坤土，对应立秋节；天五盛土：离寄戊土，土气孕育于离火，对应长夏节。以上都是说五行「成象」的阶段。</p><p>天一与地六合而成水：乾坎合、水成于金，对应冬至节；地二与天七合而成火：巽离合、火成于木，对应夏至节；天三与地八合而成木：艮震合、木成于水，对应春分节；地四与天九合而成金：坤兑合、金成于土，对应秋分节；天五与地十合而成土：离寄己土、土成于火。以上都是说五行「成形」的阶段。</p><p>用五行来说明相生相成之数，就算是儿童也能背诵；但要追究其义理真正落脚的地方，即便是老成之人也不知道。这就叫做盲目跟随古人，怎么能见到《易》的真义呢？</p><p>乃至先天诸卦：最初是一阴一阳相间，接着是二阴二阳相间，按倍数递增到三十二阴三十二阳相间。</p><p>《太玄》诸首：最初也是一阴一阳相间，接着是三阳三阴相间，按倍数递增到二十七阴二十七阳相间。这其中的道理在哪里？</p><p>用时间与万物来推演：从祖父子孙，有多寡渐变的规律；从正月到六月，有阳气从微到盛的滋长——这都是用数来说明理的方式。</p><p>应数之说，见前文。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十七章把五行的十个数字，重新钉回了<strong>节气</strong>——<strong>数的落处不在书里，在一年里。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「孕于」</strong>——这个字的关键：<strong>乾金「孕育」了坎之气。</strong> 不是「对应」，是「生育」——<strong>五行相生的方向，就是孕育的方向。</strong> 这一点让整张表从「对应表」变成了「生成链」。</li><li><strong>「成象」与「成形」</strong>——<strong>立冬是水成象，冬至是水成形。</strong> 一个季节里，气先有象、后成形——<strong>这不只是分类，是一段时间的过程。</strong></li><li><strong>「虽儿童亦能诵，纵老壮亦不知落处」</strong>——麻衣把两个极端并排放在一起，落差刺目。<strong>他知道那些口诀，问题是他不知道它们落在哪一天。</strong></li><li><strong>先天卦 2 的幂次，《太玄》3 的幂次</strong>——<strong>两种世界观</strong>。而麻衣只说「此其理何在哉」。<strong>我喜欢这个态度：他看到这两种结构，不评判，只问。</strong></li><li><strong>「以时物推之」</strong>——<strong>祖父子孙（生命）× 正月至六月（时间）</strong>。麻衣把两个最直观的节律摆出来，说：<strong>数是用来明理的，理落在时物上。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>落处是节气与时物——那节气与时物是《易》发现的，还是《易》定义的？</strong> 我的看法：<strong>麻衣会把这个问题当作「容心」来拒斥。</strong> 在他看来，冬至水气成形是自然如此，不是命名的结果。<strong>但从今天的眼光看，「冬至」本身就是观测与命名的产物。</strong> 这个张力不可消除。<strong>不过麻衣的「落处」不在「谁先谁后」，而在「是否可验证」</strong>——<strong>仲冬水泉动，这是可观察的。</strong> 在可观察这一点上，「落处」是实在的；在「谁定义谁」这一点上，它可能是循环的。<strong>而全书的力量，恰恰在可观察的那一面。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-14">第十四章 · 人之坎离</a> — 「穷理尽性」（本章的批评与此同调）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 见于日用</a> — 「《易》在日用」（本章落在节气时物）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-34">第三十四章 · 便具五数</a> — 五与十（本章五行的生数成数）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-38">第三十八章 · 生成感应</a> — 生数与成数的运行机制</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「天一地二，天三地四……天数五，地数五」</li></ul>`,27))])}}});export{y as __pageData,x as default};
